UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-solid fa-box","BrandColor":"#0061D5"}'
WHERE "Name" = 'Box.com' OR "ServerDriverKey" LIKE '%Box%';

UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-brands fa-aws","BrandColor":"#FF9900"}'
WHERE "Name" LIKE '%AWS%' OR "Name" LIKE '%S3%' OR "ServerDriverKey" LIKE '%S3%';

UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-brands fa-microsoft","BrandColor":"#0078D4"}'
WHERE "Name" LIKE '%Azure%' OR "ServerDriverKey" LIKE '%Azure%';

UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-brands fa-google-drive","BrandColor":"#0F9D58"}'
WHERE "Name" = 'Google Drive' OR "ServerDriverKey" LIKE '%Google Drive%';

UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-brands fa-google","BrandColor":"#4285F4"}'
WHERE "Name" = 'Google Cloud Storage' OR "ServerDriverKey" LIKE '%Google Cloud%';

UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-brands fa-dropbox","BrandColor":"#0061FF"}'
WHERE "Name" = 'Dropbox' OR "ServerDriverKey" LIKE '%Dropbox%';

UPDATE __mj."FileStorageProvider"
SET "Configuration" = '{"IconClass":"fa-brands fa-microsoft","BrandColor":"#038387"}'
WHERE "Name" LIKE '%SharePoint%' OR "ServerDriverKey" LIKE '%SharePoint%';

COMMENT ON COLUMN __mj."FileStorageProvider"."Configuration" IS 'Optional JSON configuration bag defining provider-level metadata and settings (shape = IFileStorageProviderConfiguration). Includes IconClass and BrandColor for UI representation.';
